## Why This Is Asked
Maintaining the median under dynamic inserts and deletes is a common, practical data-structure task that tests understanding of balanced structures and handling edge cases with duplicates.

## Key Concepts
- Median of a dynamic multiset
- Heaps: max-heap for lower half, min-heap for upper half
- Lazy deletion via hashmap to avoid O(n) removal
- Balancing logic and handling duplicates with reference counting

## Code Example
```javascript
class MedianSet {
  constructor() {
    this.low = new MaxHeap();
    this.high = new MinHeap();
    this.delLow = new Map();
    this.delHigh = new Map();
  }

  _prune() {
    while (this.low.size() > 0 && this.delLow.has(this.low.peek())) {
      const count = this.delLow.get(this.low.peek()) - 1;
      if (count <= 0) this.delLow.delete(this.low.peek());
      else this.delLow.set(this.low.peek(), count);
      this.low.pop();
    }
    while (this.high.size() > 0 && this.delHigh.has(this.high.peek())) {
      const count = this.delHigh.get(this.high.peek()) - 1;
      if (count <= 0) this.delHigh.delete(this.high.peek());
      else this.delHigh.set(this.high.peek(), count);
      this.high.pop();
    }
  }

  _rebalance() {
    if (this.low.size() > this.high.size() + 1) {
      this.high.push(this.low.pop());
    } else if (this.high.size() > this.low.size() + 1) {
      this.low.push(this.high.pop());
    }
  }

  insertScore(x) {
    if (this.low.size() === 0 || x <= this.low.peek()) {
      this.low.push(x);
    } else {
      this.high.push(x);
    }
    this._rebalance();
  }

  removeScore(x) {
    if (this.low.size() > 0 && x <= this.low.peek()) {
      const count = this.delLow.get(x) || 0;
      this.delLow.set(x, count + 1);
    } else {
      const count = this.delHigh.get(x) || 0;
      this.delHigh.set(x, count + 1);
    }
    this._prune();
    this._rebalance();
  }

  getMedian() {
    this._prune();
    if (this.low.size() > this.high.size()) return this.low.peek();
    if (this.high.size() > this.low.size()) return this.high.peek();
    return (this.low.peek() + this.high.peek()) / 2;
  }
}
```

## Why This Is Asked
Tests combining hash maps with a priority queue, handling duplicates, and lazy cleanup to keep top queries fast. Realistic usage: track most frequent items in a live feed.

## Key Concepts
- Hash map for per-item counts
- Max-heap (priority queue) for top element
- Lazy deletion to avoid costly updates
- Amortized analysis across interleaved ops

## Code Example
```javascript
class MaxHeap {
  constructor(){ this.a=[]; }
  size(){ return this.a.length; }
  push(x){ this.a.push(x); this.bubbleUp(this.a.length-1); }
  peek(){ return this.a[0]; }
  pop(){ if(!this.a.length) return null; const top=this.a[0]; const end=this.a.pop(); if(this.a.length){ this.a[0]=end; this.bubbleDown(0); } return top; }
  bubbleUp(i){ while(i>0){ const p=(i-1)>>1; if(this.a[p].count>=this.a[i].count) break; [this.a[p], this.a[i]]=[this.a[i], this.a[p]]; i=p; } }
  bubbleDown(i){ const n=this.a.length; while(true){ let l=i*2+1, r=l+1, largest=i; if(l<n && this.a[l].count>this.a[largest].count) largest=l; if(r<n && this.a[r].count>this.a[largest].count) largest=r; if(largest===i) break; [this.a[i], this.a[largest]]=[this.a[largest], this.a[i]]; i=largest; } }
}
class FrequencyDS {
  constructor(){ this.counts=new Map(); this.heap=new MaxHeap(); }
  insert(s){ const c=(this.counts.get(s)||0)+1; this.counts.set(s,c); this.heap.push({count:c, s}); }
  erase(s, cnt=1){ const old=this.counts.get(s)||0; const nc=Math.max(0, old-cnt); if(nc>0) this.counts.set(s,nc); else this.counts.delete(s); if(nc>0) this.heap.push({count:nc, s}); }
  countOf(s){ return this.counts.get(s)||0; }
  getMostFrequent(){ while(this.heap.size()){ const top=this.heap.peek(); const cur=this.counts.get(top.s)||0; if(cur!==top.count){ this.heap.pop(); continue; } return top.s; } return null; }
}
```

